module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

parameter PIPE_STAGES = 4;

reg [size-1:0] mul_a_reg;
reg [size-1:0] mul_b_reg;
reg [PIPE_STAGES-1:0] [size-1:0] partial_products;
reg [size*2-1:0] sum;
reg [PIPE_STAGES-1:0] mul_en_out_reg;
reg [size*2-1:0] mul_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_a_reg <= 0;
        mul_b_reg <= 0;
        sum <= 0;
        mul_en_out_reg <= 0;
        mul_out_reg <= 0;
    end else begin
        if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
            mul_en_out_reg <= {mul_en_out_reg[1:0], mul_en_in};
        end

        for (integer i = 0; i < size; i++) begin
            partial_products[i] <= mul_a_reg & (mul_b_reg >> i);
        end

        for (integer j = 0; j < PIPE_STAGES - 1; j++) begin
            sum <= sum + partial_products[j];
        end

        mul_out_reg <= sum;
    end
end

assign mul_en_out = mul_en_out_reg[2];
assign mul_out = mul_out_reg;

endmodule
